package org.apache.commons.lang;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class LocaleUtils_isAvailableLocale_TriageGen2Test {

    @Test
    public void testIsAvailableLocale_WithAvailableLocale() {
        // Get a set of known available locales from the utility itself to ensure test reliability
        Set<Locale> availableLocales = LocaleUtils.availableLocaleSet();
        if (!availableLocales.isEmpty()) {
            Locale availableLocale = availableLocales.iterator().next();
            assertTrue("Locale should be recognized as available", LocaleUtils.isAvailableLocale(availableLocale));
        }
    }

    @Test
    public void testIsAvailableLocale_WithUnavailableLocale() {
        // Create a locale that is highly unlikely to be in the available set
        // Using a combination of rare language and country
        Locale unavailableLocale = new Locale("zz", "ZZ");
        assertFalse("Locale should not be recognized as available", LocaleUtils.isAvailableLocale(unavailableLocale));
    }

    @Test
    public void testIsAvailableLocale_WithNull() {
        // Testing null behavior. Since the implementation uses Set.contains(locale), 
        // most Set implementations return false for null rather than throwing NPE.
        assertFalse("isAvailableLocale should return false for null", LocaleUtils.isAvailableLocale(null));
    }

    @Test
    public void testIsAvailableLocale_WithCommonLocale() {
        // Test with a very common locale to ensure standard behavior
        Locale usLocale = Locale.US;
        // We don't assert true/false strictly because the 'available' set depends on the environment,
        // but we test the logic path.
        boolean result = LocaleUtils.isAvailableLocale(usLocale);

        // If it's in the set, it's true. If not, it's false. 
        // This ensures we cover the branch logic.
        if (LocaleUtils.availableLocaleSet().contains(usLocale)) {
            assertTrue(result);
        } else {
            assertFalse(result);
        }
    }
}
